import re

def normalize(text):
    """Remove explicit transient review records only; preserve product prose."""
    lines=text.splitlines(keepends=True)
    out=[]; skipped=[]; depth=None
    for line in lines:
        m=re.match(r"^(#{1,6})\s+(.*)",line)
        if depth is not None:
            if m and len(m[1]) <= depth:
                depth=None
            else:
                skipped.append(line); continue
        if m and re.search(r"review record|review status|review evidence|review coverage|review findings",m[2],re.I):
            depth=len(m[1]); skipped.append(line); continue
        if re.match(r"^(?:\*\*)?Review (?:status|record|coverage)[: ]",line,re.I):
            skipped.append(line); continue
        out.append(line)
    return "".join(out), "".join(skipped)

